using System;using System.Drawing;using System.IO;using System.Linq;using System.Collections.Generic;using System.IO.Compression;using System.Windows.Forms;using ContourWatch;
class DiagnosticsTests{
 [STAThread] static int Main(string[] args){try{Agent.Root=Path.GetFullPath(args[0]);if(args.Length>1&&args[1]=="--show"){Application.EnableVisualStyles();Application.Run(new DiagnosticWindow(Agent.Root));return 0;}Directory.CreateDirectory(Agent.Root);Directory.CreateDirectory(Path.Combine(Agent.Root,"queue"));File.WriteAllText(Path.Combine(Agent.Root,"config.json"),"PRIVATE_CONFIG_TOKEN");File.WriteAllText(Path.Combine(Agent.Root,"queue","sample.json"),"PRIVATE_QUEUE");
  var metrics=new List<Dictionary<string,object>>{Collectors.Metric("cpu:temperature","temperature","CPU Package","unsupported",null,"°C",Agent.Obj("reason","Требуется PawnIO token=HIDDEN_TOKEN","pawnIoInstalled",false,"serial","PRIVATE_SERIAL","raw",Agent.Obj("secret","PRIVATE_RAW"))),Collectors.Metric("gpu:temperature","gpu_temperature","Test GPU","error",null,"°C",Agent.Obj("errorType","TimeoutException","message","password=HIDDEN_PASSWORD timeout"))};
  DiagnosticReport.Record("sensors",metrics,120);string snapshot=File.ReadAllText(Path.Combine(Agent.Root,"public","diagnostics.json"));string text=DiagnosticReport.Text(Agent.Root);if(!text.Contains("PawnIO")||!text.Contains("TimeoutException")||!text.Contains("unsupported"))throw new Exception("Missing diagnostic reason/state");foreach(string secret in new[]{"HIDDEN_TOKEN","HIDDEN_PASSWORD","PRIVATE_SERIAL","PRIVATE_RAW","PRIVATE_CONFIG_TOKEN","PRIVATE_QUEUE"})if(snapshot.Contains(secret)||text.Contains(secret))throw new Exception("Private value leaked");
  string log=Path.Combine(Agent.Root,"public","diagnostics.log");long length=new FileInfo(log).Length;DiagnosticReport.Record("sensors",metrics,130);if(new FileInfo(log).Length!=length)throw new Exception("Unchanged metric state spammed log");metrics[0]["state"]="ok";metrics[0]["details"]=null;DiagnosticReport.Record("sensors",metrics,140);if(new FileInfo(log).Length<=length)throw new Exception("Recovery not logged");
  string zip=Path.Combine(Agent.Root,"public-export.zip");DiagnosticReport.ExportPublic(Agent.Root,zip);using(var archive=ZipFile.OpenRead(zip)){if(archive.GetEntry("diagnostics.txt")==null||archive.GetEntry("diagnostics.json")==null)throw new Exception("Incomplete export");foreach(var entry in archive.Entries){if(entry.FullName.Contains("config")||entry.FullName.Contains("queue"))throw new Exception("Private file included");using(var reader=new StreamReader(entry.Open())){string content=reader.ReadToEnd();if(content.Contains("PRIVATE_")||content.Contains("HIDDEN_"))throw new Exception("Private export value");}}}bool rejected=false;try{DiagnosticReport.ExportPublic(Agent.Root,zip);}catch(IOException){rejected=true;}if(!rejected)throw new Exception("Existing file overwritten without prompt");
  using(var window=new DiagnosticWindow(Agent.Root)){if(window.Controls.OfType<TextBox>().Single().ReadOnly!=true)throw new Exception("Editable log viewer");if(!window.Controls.OfType<TextBox>().Single().Text.Contains("PawnIO"))throw new Exception("Viewer does not render diagnostic report");}
  string oldTheme=AgentTheme.Preference;try{AgentTheme.Save("dark");using(var form=new Form()){var textBox=new TextBox();var check=new AgentTheme.AgentCheckBox{Text="Auto"};form.Controls.Add(textBox);form.Controls.Add(check);form.Controls.Add(AgentTheme.Picker(form));AgentTheme.Apply(form);foreach(Control c in form.Controls)if(c.BackColor.R>70||c.BackColor.G>90||c.BackColor.B>90)throw new Exception("Light control in dark theme: "+c.GetType().Name);}using(var save=new AgentSaveDialog(".txt")){foreach(Control c in save.Controls)if(c.BackColor.R>70)throw new Exception("Light save dialog in dark theme");}AgentTheme.Save("light");using(var form=new Form()){AgentTheme.Apply(form);if(form.BackColor.R<200)throw new Exception("Light theme did not restore");}}finally{AgentTheme.Save(oldTheme);}
  File.AppendAllText(log,new string('x',270000));AgentLog.Write("info","test","rotation","Test");if(new FileInfo(log).Length>262144||!File.Exists(log+".1"))throw new Exception("Public rotation unbounded");
  Console.WriteLine("PASS diagnostic reasons, state changes/recovery, redaction, public-only ZIP, overwrite protection, real WinForms viewer and log rotation");return 0;
 }catch(Exception e){Console.Error.WriteLine(e.ToString());return 1;}}
}
